{
	"name": "oc-transcript-save",
	"description": "OpenCode plugin that autosaves full transcript in specified directory",
	"version": "0.2.3",
	"type": "module",
	"main": "./index.ts",
	"module": "./index.ts",
	"types": "./index.ts",
	"exports": {
		".": {
			"types": "./index.ts",
			"import": "./index.ts"
		},
		"./server": {
			"types": "./index.ts",
			"import": "./index.ts"
		},
		"./v1": {
			"types": "./transcript-save.ts",
			"import": "./transcript-save.ts"
		}
	},
	"author": "Umar Alfarouk <medrivia@gmail.com>",
	"scripts": {
		"prepublishOnly": "bun run check",
		"check": "bun tsc --noEmit",
		"fmt": "dprint fmt"
	},
	"files": [
		"index.ts",
		"transcript-save.ts",
		"tsconfig.json",
		"README.md"
	],
	"keywords": [
		"opencode",
		"plugin",
		"transcript"
	],
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/mdrv/oc-transcript-save.git"
	},
	"homepage": "https://github.com/mdrv/oc-transcript-save",
	"dependencies": {},
	"devDependencies": {
		"@opencode-ai/plugin": "1.17.11",
		"@types/bun": "latest"
	},
	"peerDependencies": {
		"typescript": "^5"
	}
}
